import{Component}from'../../core/index.js';import{THREE}from'./geometry.js';
/** Actual single blue LED; external appearance only, no input or firmware echo. */
export class StatusLed extends Component{static kind='led';constructor({mesh,...opts}){super(opts);this.color=new THREE.Color(0x168aff);this.brightness=0;this.lens=mesh;this.object3d.add(mesh);this.lensMaterial=mesh.material;this.lensMaterial.emissive=new THREE.Color(0);}
set(value){const s=typeof value==='boolean'?{on:value}:value;if(!s||typeof s!=='object')throw new TypeError('status expects on/brightness');if(s.color!=null&&new THREE.Color(s.color).getHex()!==this.color.getHex())throw new RangeError('TimerCamera-F physical indicator is fixed blue');if(s.brightness!=null){if(!Number.isFinite(s.brightness))throw new TypeError('brightness must be finite');this.brightness=Math.max(0,Math.min(1,s.brightness));}else if(s.on!=null)this.brightness=s.on?1:0;this.lensMaterial.emissive.copy(this.color).multiplyScalar(this.brightness*2);this.requestRender();return this.getState();}handle(cmd){if(cmd.type==='led')return this.set(cmd);return super.handle(cmd);}getState(){return{color:'#168aff',brightness:this.brightness};}}
